*   **`table class="table table-striped"`:**  Uses Bootstrap's base table styling and striped rows.
*   **`<thead>`:**  Contains the table headers.
*   **`<th>`:**  Each header cell.  Crucially, we add a `data-sort` attribute to each `<th>`.  This attribute tells our JavaScript what type of sorting to apply to that column.  Possible values:
    *   `string`: For text-based sorting (alphanumeric).
    *   `number`: For numeric sorting.
    *   `date`: For date sorting (assuming a consistent date format like YYYY-MM-DD).
*   **`<tbody>`:**  Contains the table data rows.
*   **`<tr>`:**  Each data row.
*   **`<td>`:**  Each data cell.

**2. JavaScript (Sorting Logic)**

```javascript
document.addEventListener('DOMContentLoaded', function() {
  const table = document.querySelector('.table'); // Select the table
  if (!table) return; // Exit if no table found

  const headers = table.querySelectorAll('th');

  headers.forEach(header => {
    header.addEventListener('click', function() {
      const sortType = this.dataset.sort;
      const columnIndex = Array.from(headers).indexOf(this); // Get column index

      // Get the table body
      const tbody = table.querySelector('tbody');
      const rows = Array.from(tbody.querySelectorAll('tr'));

      // Sort the rows
      rows.sort((a, b) => {
        const cellA = a.querySelectorAll('td')[columnIndex].textContent;
        const cellB = b.querySelectorAll('td')[columnIndex].textContent;

        let comparison = 0;

        switch (sortType) {
          case 'string':
            comparison = cellA.localeCompare(cellB);
            break;
          case 'number':
            comparison = parseFloat(cellA) - parseFloat(cellB);
            break;
          case 'date':
            comparison = new Date(cellA) - new Date(cellB);
            break;
          default:
            comparison = cellA.localeCompare(cellB); // Default to string
        }

        return comparison;
      });

      // Re-append the sorted rows to the table body
      tbody.innerHTML = '';
      rows.forEach(row => tbody.appendChild(row));

      // Add a class to the clicked header to indicate sorting direction
      headers.forEach(h => h.classList.remove('sorted-asc', 'sorted-desc'));
      this.classList.toggle('sorted-asc', comparison > 0);
      this.classList.toggle('sorted-desc', comparison < 0);
    });
  });
});
```

