        // Attempt to get the user's Firebase ID token from the request headers
        $idToken = request_headers('Authorization');

        if ($idToken) {
            try {
                $decodedToken = $firebase->verifyIdToken($idToken);
                $uid = $decodedToken->uid;

                // User is authenticated via Firebase (even as a guest)
                // You can now use the $uid to identify the user
                auth()->setUser($uid); // Laravel Auth::user() will now return the Firebase UID

                return view('guest.index', ['uid' => $uid]);
            } catch (\Exception $e) {
                // Invalid token or other Firebase authentication error
                // Handle the error appropriately (e.g., redirect to a login page)
                return view('guest.error', ['error' => $e->getMessage()]);
            }
        } else {
            // No token provided - treat as an unauthenticated guest
            return view('guest.index', ['uid' => null]);
        }
    }
}
