// MARK: - AST Nodes

/// Represents a node in the Metal Shading Language Abstract Syntax Tree (AST).
protocol ASTNode {
    /// A textual representation of the node, useful for debugging.
    var description: String { get }
}

// MARK: - Expression Nodes

/// Represents an expression in the Metal Shading Language.
protocol ExpressionNode: ASTNode {
    /// Type of the expression.
    var type: MetalType { get }
}

/// Represents a constant expression.
struct ConstantExpressionNode: ExpressionNode {
    let value: ConstantValue
    let type: MetalType

    var description: String {
        return "Constant(\(value))"
    }
}

/// Represents a variable expression.
struct VariableExpressionNode: ExpressionNode {
    let name: String
    let type: MetalType

    var description: String {
        return "Variable(\(name))"
    }
}

/// Represents a binary expression (e.g., +, -, *, /).
struct BinaryExpressionNode: ExpressionNode {
    let left: ExpressionNode
    let right: ExpressionNode
    let operatorSymbol: String
    let type: MetalType

    var description: String {
        return "Binary(\(left.description), \(operatorSymbol), \(right.description))"
    }
}

/// Represents a function call expression.
struct FunctionCallExpressionNode: ExpressionNode {
    let functionName: String
    let arguments: [ExpressionNode]
    let type: MetalType

    var description: String {
        return "FunctionCall(\(functionName), \(arguments.description))"
    }
}

// MARK: - Statement Nodes

