import AsyncStorage from '@react-native-async-storage/async-storage';

const SettingsScreen = ({ navigation }) => {
  const [notificationsEnabled, setNotificationsEnabled] = useState(true);
  const [theme, setTheme] = useState('light'); // Default theme

  useEffect(() => {
    // Load settings from AsyncStorage when the component mounts
    const loadSettings = async () => {
      try {
        const storedNotifications = await AsyncStorage.getItem('notificationsEnabled');
        const storedTheme = await AsyncStorage.getItem('theme');

        if (storedNotifications !== null) {
          setNotificationsEnabled(JSON.parse(storedNotifications));
        }
        if (storedTheme !== null) {
          setTheme(storedTheme);
        }
      } catch (error) {
        console.error('Error loading settings:', error);
      }
    };

    loadSettings();
  }, []);

  const toggleNotifications = () => {
    setNotificationsEnabled(!notificationsEnabled);
    // Save the new setting to AsyncStorage
    saveSetting('notificationsEnabled', !notificationsEnabled);
  };

  const toggleTheme = () => {
    setTheme(theme === 'light' ? 'dark' : 'light');
    saveSetting('theme', theme === 'light' ? 'dark' : 'light');
  };

  const saveSetting = async (key, value) => {
    try {
      await AsyncStorage.setItem(key, JSON.stringify(value));
    } catch (error) {
      console.error(`Error saving setting ${key}:`, error);
    }
  };

  return (
    <ScrollView style={styles.container}>
      <View style={styles.settingItem}>
        <Text style={styles.settingLabel}>Notifications</Text>
        <Switch
          value={notificationsEnabled}
          onValueChange={toggleNotifications}
        />
      </View>

      <View style={styles.settingItem}>
        <Text style={styles.settingLabel}>Theme</Text>
        <Switch
          value={theme === 'light'}
          onValueChange={toggleTheme}
        />
      </View>
    </ScrollView>
  );
};

