    </div>
  );
}

function ChildComponent(props) {
  return <div>Child: {props.message}</div>;
}

function App() {
  return (
    <ParentComponent>
      <React.cloneElement(<ChildComponent />, { message: "Hello from Parent!" })
      </ParentComponent>
  );
}
```

